WITH site_hourly AS (SELECT wsit.web_site_id, td.t_hour, SUM(ws.ws_net_profit) AS hourly_profit, ROW_NUMBER() OVER (PARTITION BY wsit.web_site_id ORDER BY SUM(ws.ws_net_profit) DESC) AS rank FROM web_sales ws JOIN time_dim td ON ws.ws_sold_time_sk = td.t_time_sk JOIN web_site wsit ON ws.ws_web_site_sk = wsit.web_site_sk GROUP BY wsit.web_site_id, td.t_hour) SELECT web_site_id, t_hour, hourly_profit, CASE WHEN rank = 1 THEN 'Top Hour' ELSE 'Other Hour' END AS hour_category FROM site_hourly WHERE rank <= 3 ORDER BY web_site_id, rank
